package net.mca.client.book;

import net.mca.client.book.pages.Page;
import net.mca.client.book.pages.SimpleListPage;
import net.mca.client.book.pages.TitlePage;
import net.mca.cobalt.network.NetworkHandler;
import net.mca.network.c2s.CivilRegistryPageRequest;
import net.mca.util.localization.FlowingText;
import net.minecraft.text.Text;

import java.util.*;

public class CivilRegistryBook extends Book {
    Set<Integer> requestedPages = new HashSet<>();
    HashMap<Integer, Page> loadedPages = new HashMap<>();
    int lastIndex = 0;

    Page EMPTY = new TitlePage("...", "");

    public CivilRegistryBook(String bookName, Text bookAuthor) {
        super(bookName, bookAuthor);
    }

    @Override
    public void open() {
        super.open();

        requestedPages.clear();
        loadedPages.clear();
        lastIndex = 0;
    }

    @Override
    public int getPageCount() {
        return 9999;
    }

    @Override
    public boolean showPageCount() {
        return false;
    }

    @Override
    public Page getPage(int index) {
        if (!requestedPages.contains(index) && (requestedPages.contains(index - 1) || index == 0)) {
            requestedPages.add(index);
            NetworkHandler.sendToServer(new CivilRegistryPageRequest(index, lastIndex, lastIndex + 14));
        }

        if (loadedPages.containsKey(index)) {
            return loadedPages.get(index);
        } else {
            return EMPTY;
        }
    }

    public void receive(int index, List<Text> lines) {
        List<Text> text = new LinkedList<>();
        for (Text line : lines) {
            List<Text> wrap = FlowingText.wrap(line, 110);
            if (text.size() + wrap.size() > 14) {
                break;
            }
            int i = 0;
            for (Text l : wrap) {
                if (i == 0) {
                    text.add(l);
                } else {
                    text.add(Text.literal(" ").append(l));
                }
                i++;
            }
            lastIndex++;
        }

        loadedPages.put(index, new SimpleListPage(text));
    }
}

package net.mca.client.book.pages;

import net.minecraft.text.Text;

import java.util.LinkedList;
import java.util.List;

public abstract class ListPage extends Page {
    final List<Text> text;

    int page;

    public ListPage() {
        this.text = new LinkedList<>();
    }

    public ListPage(List<Text> text) {
        this.text = text;
    }

    @Override
    public void open(boolean back) {
        page = back ? (text.size() - 1) / getEntriesPerPage() : 0;
    }

    @Override
    public boolean previousPage() {
        if (page > 0) {
            page--;
            return false;
        } else {
            return true;
        }
    }

    @Override
    public boolean nextPage() {
        if (page < (text.size() - 1) / getEntriesPerPage()) {
            page++;
            return false;
        } else {
            return true;
        }
    }

    abstract int getEntriesPerPage();
}

package net.mca.client.book.pages;

import net.mca.client.gui.ExtendedBookScreen;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.text.Text;

import java.util.List;

public class SimpleListPage extends ListPage {
    public SimpleListPage(List<Text> text) {
        super(text);
    }

    @Override
    int getEntriesPerPage() {
        return 14;
    }

    @Override
    public void render(ExtendedBookScreen screen, DrawContext context, int mouseX, int mouseY, float delta) {
        int y = 20;
        for (int i = page * getEntriesPerPage(); i < Math.min(text.size(), (page + 1) * getEntriesPerPage()); i++) {
            context.drawText(screen.getTextRenderer(), text.get(i), (screen.width - 192) / 2 + 36, y, 0xFF000000, screen.getBook().hasTextShadow());
            y += 10;
        }
    }
}

